function esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
function fmtCur(n){ return "$" + Number(n || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function render(){
  var m = appsmith.model || {};
  var rows = m.rows || [];
  var html = '<div class="hd"><h2>Bill History</h2><span class="x" id="closeX">×</span></div>';
  html += '<div class="tblwrap"><table><thead><tr>'
        + '<th>Bill ID</th><th>Invoice Date</th><th>Charges</th><th>Consumption</th><th>Max Demand</th><th>Gen Consumption</th>'
        + '</tr></thead><tbody>';
  if (m.isLoading) {
    html += '<tr><td colspan="6" class="empty">Loading…</td></tr>';
  } else if (!rows.length) {
    html += '<tr><td colspan="6" class="empty">No bills found</td></tr>';
  } else {
    rows.forEach(function(r){
      html += '<tr>'
        + '<td class="link">' + esc(r["Bill ID"]) + '</td>'
        + '<td>' + esc(r["Invoice Date"]) + '</td>'
        + '<td>' + fmtCur(r["Charges"]) + '</td>'
        + '<td>N/A</td><td>N/A</td><td>N/A</td>'
        + '</tr>';
    });
  }
  html += '</tbody></table></div>';
  var root = document.getElementById("root"); if(!root) return;
  root.innerHTML = html;
  var x = document.getElementById("closeX"); if (x) x.onclick = function(){ appsmith.triggerEvent("onClose"); };
}
appsmith.onReady(function(){ render(); appsmith.onModelChange(render); });

